#include <bits/stdc++.h>
#include "opelib.h"
using namespace std;

int rozmiar;
vector<int> tablica;
vector<vector<int>> prefsuf;

void rozbij(int poziom,int poczatek,int koniec){
    if(poczatek>=koniec || poziom>10)return;
    int srodek=(poczatek+koniec)/2;

    //Sufiksy
    prefsuf[poziom][srodek]=tablica[srodek];
    for(int i=srodek-1;i>=poczatek;i--){
        prefsuf[poziom][i]=zapytaj(tablica[i],prefsuf[poziom][i+1]);
    }
    

    //Prefiksy
    if(srodek+1<=koniec)prefsuf[poziom][srodek+1]=tablica[srodek+1];
    for(int i=srodek+2;i<=koniec;i++){
        prefsuf[poziom][i]=zapytaj(prefsuf[poziom][i-1],tablica[i]);
    }   
    
    rozbij(poziom+1,poczatek,srodek);
    rozbij(poziom+1,srodek+1,koniec);
    return;
}

int znajdz(int poziom,int poczatek,int koniec,int l,int r){
    if(poczatek>=koniec || poziom>10)return 0;
    int srodek=(poczatek+koniec)/2;

    if(l<=srodek && r>srodek){
        return zapytaj(prefsuf[poziom][l],prefsuf[poziom][r]);
    }

    if(l<=srodek){
       return znajdz(poziom+1,poczatek,srodek,l,r);
    }else{
        if(l>srodek){
            return znajdz(poziom+1,srodek+1,koniec,l,r);
        }
    }

    return 0;
}

void rozpocznij(int n, int tab[]){
    rozmiar=n;
    tablica.resize(rozmiar+1);

    for(int i=0;i<rozmiar;i++){
        tablica[i]=tab[i];
    }

    prefsuf.resize(11,vector<int>(rozmiar));
    rozbij(0,0,rozmiar-1);
}

int odpowiedz(int l, int r){
    if(l==r){
        return tablica[l];
    }else{
        if(l+1==r){
            return zapytaj(tablica[l],tablica[r]);
        }else{
            return znajdz(0,0,rozmiar-1,l,r);
        }
    }
}
